-- STEP12: enforce branch and cashier desk scope in legacy operational alerts.
CREATE OR REPLACE FUNCTION public.ff40_operations_alerts(p_branch uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
                                                                                                                                                                                                                                                     DECLARE
                                                                                                                                                                                                                                                      v_uid uuid:=auth.uid();
                                                                                                                                                                                                                                                       v_role text;
                                                                                                                                                                                                                                                        v_result jsonb;
                                                                                                                                                                                                                                                        BEGIN
                                                                                                                                                                                                                                                         SELECT role INTO v_role FROM public.ff_profiles WHERE user_id=v_uid AND active=true;
                                                                                                                                                                                                                                                          IF v_role IS NULL OR v_role NOT IN ('manager','customer_service','supervisor','cashier')
                                                                                                                                                                                                                                                              OR NOT public.ff38_permission_allowed(v_uid,'view_reports') THEN
                                                                                                                                                                                                                                                                 RAISE EXCEPTION 'ليس لديك صلاحية متابعة التنبيهات التشغيلية' USING ERRCODE='42501';
                                                                                                                                                                                                                                                                  END IF;
                                                                                                                                                                                                                                                                   IF p_branch IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.ff_branches WHERE id=p_branch AND ff_private.a10_branch_visible(v_role,p_branch)) THEN RAISE EXCEPTION 'الفرع غير مصرح به' USING ERRCODE='42501'; END IF;

                                                                                                                                                                                                                                                                     WITH scope AS MATERIALIZED (
                                                                                                                                                                                                                                                                       SELECT o.id,o.order_number,o.branch_id,o.status,o.created_at,o.area_snapshot,
                                                                                                                                                                                                                                                                           t.order_id AS task_order_id,t.driver_id,t.phase,t.cashier_stage,
                                                                                                                                                                                                                                                                               t.assigned_at,t.picked_up_at,t.delivered_at
                                                                                                                                                                                                                                                                                 FROM public.ff_orders o
                                                                                                                                                                                                                                                                                   LEFT JOIN public.ff38_delivery_tasks t ON t.order_id=o.id
                                                                                                                                                                                                                                                                                     WHERE o.order_type='delivery'
                                                                                                                                                                                                                                                                                        AND o.status NOT IN ('delivered','cancelled')
                                                                                                                                                                                                                                                                                           AND o.created_at>now()-interval '14 days'
                                                                                                                                                                                                                                                                                              AND (p_branch IS NULL OR o.branch_id=p_branch)
                                                                                                                                                                                                                                                                                                 AND ff_private.a10_branch_visible(v_role,o.branch_id) AND (v_role<>'cashier' OR ff_private.a05_can_read_order(o.id))
                                                                                                                                                                                                                                                                                                             ),
                                                                                                                                                                                                                                                                                                              alerts AS (
                                                                                                                                                                                                                                                                                                                SELECT 'waiting'::text AS kind,2 AS severity,s.id AS order_id,s.order_number,s.branch_id,
                                                                                                                                                                                                                                                                                                                    'طلب ينتظر الموصل'::text AS title,
                                                                                                                                                                                                                                                                                                                        'لم يُسند الطلب منذ أكثر من 15 دقيقة'::text AS description,
                                                                                                                                                                                                                                                                                                                            s.created_at AS since_at
                                                                                                                                                                                                                                                                                                                              FROM scope s WHERE s.task_order_id IS NULL AND s.created_at<=now()-interval '15 minutes'
                                                                                                                                                                                                                                                                                                                                UNION ALL
                                                                                                                                                                                                                                                                                                                                  SELECT 'cashier',2,s.id,s.order_number,s.branch_id,'تأخر تجهيز الطلب',
                                                                                                                                                                                                                                                                                                                                      'الطلب مسند لكن الكاشير لم يؤكد التسليم للموصل منذ أكثر من 25 دقيقة',s.assigned_at
                                                                                                                                                                                                                                                                                                                                        FROM scope s WHERE s.task_order_id IS NOT NULL AND s.cashier_stage<>'handed_over'
                                                                                                                                                                                                                                                                                                                                            AND s.assigned_at<=now()-interval '25 minutes'
                                                                                                                                                                                                                                                                                                                                              UNION ALL
                                                                                                                                                                                                                                                                                                                                                SELECT 'delivery',3,s.id,s.order_number,s.branch_id,'تأخر تسليم الطلب',
                                                                                                                                                                                                                                                                                                                                                    'الموصل في الطريق منذ أكثر من 40 دقيقة دون تسجيل التسليم',s.picked_up_at
                                                                                                                                                                                                                                                                                                                                                      FROM scope s WHERE s.phase IN ('on_way','arrived')
                                                                                                                                                                                                                                                                                                                                                          AND s.picked_up_at<=now()-interval '40 minutes' AND s.delivered_at IS NULL
                                                                                                                                                                                                                                                                                                                                                            UNION ALL
                                                                                                                                                                                                                                                                                                                                                              SELECT 'addition',2,s.id,s.order_number,s.branch_id,'إضافة لم تُفوتر',
                                                                                                                                                                                                                                                                                                                                                                  'إضافة على الطلب تنتظر تأكيد فاتورة الكاشير لأكثر من 15 دقيقة',a.created_at
                                                                                                                                                                                                                                                                                                                                                                    FROM scope s JOIN public.ff38_order_additions a ON a.order_id=s.id
                                                                                                                                                                                                                                                                                                                                                                      WHERE a.status='pending' AND a.created_at<=now()-interval '15 minutes'
                                                                                                                                                                                                                                                                                                                                                                        UNION ALL
                                                                                                                                                                                                                                                                                                                                                                          SELECT 'driver_offline',3,s.id,s.order_number,s.branch_id,'موصل غير متصل',
                                                                                                                                                                                                                                                                                                                                                                              'الموصل مرتبط بطلب نشط واتصاله منقطع لأكثر من 3 دقائق',
                                                                                                                                                                                                                                                                                                                                                                                  COALESCE(p.last_seen_at,s.assigned_at)
                                                                                                                                                                                                                                                                                                                                                                                    FROM scope s JOIN public.ff38_driver_presence p ON p.driver_id=s.driver_id
                                                                                                                                                                                                                                                                                                                                                                                      WHERE s.task_order_id IS NOT NULL AND s.delivered_at IS NULL
                                                                                                                                                                                                                                                                                                                                                                                          AND s.assigned_at<=now()-interval '5 minutes'
                                                                                                                                                                                                                                                                                                                                                                                              AND (p.state='offline' OR p.last_seen_at IS NULL OR p.last_seen_at<=now()-interval '3 minutes')
                                                                                                                                                                                                                                                                                                                                                                                               ),
                                                                                                                                                                                                                                                                                                                                                                                                selected AS (
                                                                                                                                                                                                                                                                                                                                                                                                  SELECT kind,severity,order_id,order_number,branch_id,title,description,
                                                                                                                                                                                                                                                                                                                                                                                                      since_at,pg_catalog.floor(EXTRACT(EPOCH FROM(now()-since_at))/60)::integer AS age_minutes
                                                                                                                                                                                                                                                                                                                                                                                                        FROM alerts ORDER BY severity DESC,since_at ASC,order_number LIMIT 50
                                                                                                                                                                                                                                                                                                                                                                                                         )
                                                                                                                                                                                                                                                                                                                                                                                                          SELECT pg_catalog.jsonb_build_object(
                                                                                                                                                                                                                                                                                                                                                                                                             'items',COALESCE((SELECT pg_catalog.jsonb_agg(to_jsonb(x) ORDER BY x.severity DESC,x.since_at ASC) FROM selected x),'[]'::jsonb),
                                                                                                                                                                                                                                                                                                                                                                                                                'count',(SELECT count(*) FROM selected),
                                                                                                                                                                                                                                                                                                                                                                                                                   'checked_at',now()
                                                                                                                                                                                                                                                                                                                                                                                                                    ) INTO v_result;
                                                                                                                                                                                                                                                                                                                                                                                                                     RETURN v_result;
                                                                                                                                                                                                                                                                                                                                                                                                                     END $function$;
